SELECT b.* FROM the_full_order.tb_account_inventory_balance b
WHERE b.account_id=#{account_id} AND b.ingredient_id=#{ingredient_id}
ORDER BY b.created_at,b.inventory_balance_id FOR UPDATE

SELECT * FROM the_full_order.tb_account_inventory_lot WHERE account_id=#{account_id}
 AND ingredient_id=#{ingredient_id} AND location_id=#{location_id}
 AND remaining_base_qty>0 ORDER BY received_date,inventory_lot_id FOR UPDATE
